    "description": "国新办举行“开局起步‘十五五’”系列主题新闻发布会。发布会上，农业农村部有关负责人介绍，“十五五”时期，将突出科技改革双轮驱动，加快推进农业农村现代化。将协同推进科技创新和制度创新，塑造农业农村高质量发展新动能新优势。一方面，大力推进高水平农业科技自立自强，推动科技创新和产业创新深度融合，促进良田良种良机良法集成增效，让新质生产力成为现代农业发展的“新引擎”。另一方面，坚持处理好农民和土地关系这条主线，持续深化第二轮土地承包到期后再延长…",
    "content": "国新办举行“开局起步‘十五五’”系列主题新闻发布会。发布会上，农业农村部有关负责人介绍，“十五五”时期，将突出科技改革双轮驱动，加快推进农业农村现代化。将协同推进科技创新和制度创新，塑造农业农村高质量发展新动能新优势。一方面，大力推进高水平农业科技自立自强，推动科技创新和产业创新深度融合，促进良田良种良机良法集成增效，让新质生产力成为现代农业发展的“新引擎”。另一方面，坚持处理好农民和土地关系这条主线，持续深化第二轮土地承包到期后再延长30年试点等农村改革重点任务，稳固集体所有制根基，保障农民集体成员权利，激活农村…"
