    "description": "“为救李郎离家园，谁料皇榜中状元……”婉转的黄梅戏唱腔，回荡在安徽省怀宁县石牌镇的老街巷弄。老话讲“梨园佳子弟，无石不成班”，石牌镇，这座皖水、潜水、长河三水交汇的千年古镇，戏曲底蕴深厚，走出过高朗亭、程长庚、杨小楼、严凤英等一大批戏曲名家，是远近闻名的戏曲“戏窝子”。",
