    "description": "中新网济宁9月29日电(周艺伟 祁建月)9月25日至28日，由教育部中外人文交流中心、山东省教育厅、济宁市人民政府主办的2026中外青年学生孔子文化周(简称“孔子文化周”)在山东济宁举办。为期四天的活动中，来自49个国家和地区的170余名青年师生从尼山圣境到机器人产业园，从匹克球场到孔庙，在行走与对话中完成一次文明互鉴的青春实践。",
    "content": "中新网济宁9月29日电(周艺伟 祁建月)9月25日至28日，由教育部中外人文交流中心、山东省教育厅、济宁市人民政府主办的2026中外青年学生孔子文化周(简称“孔子文化周”)在山东济宁举办。为期四天的活动中，来自49个国家和地区的170余名青年师生从尼山圣境到机器人产业园，从匹克球场到孔庙，在行走与对话中完成一次文明互鉴的青春实践。"
