    "description": "2024年4月29日晚，陕西白河县一女教师薛某荣在回家途中被两辆车先后撞击碾压，其中第二辆车将薛某荣拖行了5.9公里，最终薛某荣死亡。 9月28日，记者从被害人薛某荣的妹妹薛某莉处获悉，目前，涉案的五人都以涉嫌故意杀人被提起公诉。此前这五人中有两人因涉嫌交通肇事罪被起诉，一人因涉嫌包庇罪被起诉，另两人则未被追责。 薛某荣生前照片 事后找人“顶包” 销毁行车记录仪存储卡 2024年4月29日20时40分许，刘某祥驾驶车辆将前方同向行走的薛…",
    "content": "2024年4月29日晚，陕西白河县一女教师薛某荣在回家途中被两辆车先后撞击碾压，其中第二辆车将薛某荣拖行了5.9公里，最终薛某荣死亡。 9月28日，记者从被害人薛某荣的妹妹薛某莉处获悉，目前，涉案的五人都以涉嫌故意杀人被提起公诉。此前这五人中有两人因涉嫌交通肇事罪被起诉，一人因涉嫌包庇罪被起诉，另两人则未被追责。 薛某荣生前照片 事后找人“顶包” 销毁行车记录仪存储卡 2024年4月29日20时40分许，刘某祥驾驶车辆将前方同向行走的薛某荣撞倒并碾轧，之后刘某祥减速靠右将车停在非机动车道上，下车查看情况并电话报警。…"
