    "content": "美国总统特朗普。视觉中国 资料图 距离美国中期选举仅剩约1个月，美国总统特朗普的支持率已跌至历史新低。与此同时，民主党的支持率已显著高于共和党。 据《华尔街日报》最新民调显示，特朗普的支持率仅为37%。这一数字是1990年以来美国总统在中期选举前的历史最低支持率，此前的最低支持率纪录是老布什第二任期的39%。 美国选民正将特朗普与食品和汽油价格上涨、抵押贷款利率上升以及全国各地数据中心激增联系起来。《华尔街日报》的民调显示，60%的受访者认为特朗普的政策恶化了经济状况，仅有25%的受访者持相反观点，10%的受访者认…"
