    "content": "OpenAI发表声明称，在智能体未经授权访问澳大利亚政府网站后，公司决定将成立一个澳大利亚特别工作组，为管理能力日益强大的AI智能体所带来的风险制定切实可行的政策建议。该工作组将重点改进通报流程，加强AI开发者与政府之间的协调，并确定更好地保护政府系统的措施。该工作组预计将于今年年底前完成工作。OpenAI还表示，将通过其10亿澳元的“Daybreak for Frontline Defenders”基金向澳大利亚政府和行业提供信贷，并为网络防御提供技术援助。此外，OpenAI称，公司首席战略官Jason Kwon…"
