    "pub_date": "2026-09-29 09:44:31",
    "author": "",
    "description": "中新网北京9月29日电 (记者 李京泽)中央政法委9月28日发布关于授牌命名2021—2025年度平安中国建设示范市、县的决定(以下简称决定)，授予河北省衡水市等60个市(地、州)“2021—2025年度平安中国建设示范市”称号，授予北京市西城区等160个县(市、区)“2021—2025年度平安中国建设示范县”称号。",
    "content": "中新网北京9月29日电 (记者 李京泽)中央政法委9月28日发布关于授牌命名2021—2025年度平安中国建设示范市、县的决定(以下简称决定)，授予河北省衡水市等60个市(地、州)“2021—2025年度平安中国建设示范市”称号，授予北京市西城区等160个县(市、区)“2021—2025年度平安中国建设示范县”称号。"
