    "pub_date": "2026-09-29 09:41:35",
    "author": "澎湃新闻记者 庄岸",
    "description": "针对“嘉陵江亭子湖库区出现大量死鱼”现象，9月29日，广元市水产技术推广站通报称，经综合研判，局部地区晴热高温与短时强降雨交替叠加，造成水体表层水温剧烈波动，引发鳙鱼（花鲢）产生应激反应，鱼鳃受损后继发维氏气单胞菌感染，致使库区表层鳙鱼（花鲢）死亡。 通报称，近日，亭子湖库区部分水域出现鳙鱼（花鲢）死亡现象。各级各相关部门高度重视，第一时间组织开展打捞处置和原因调查。经四川省重点实验室对送检样本开展病原检测，结合鱼病、水生态领域专家现场…",
    "content": "针对“嘉陵江亭子湖库区出现大量死鱼”现象，9月29日，广元市水产技术推广站通报称，经综合研判，局部地区晴热高温与短时强降雨交替叠加，造成水体表层水温剧烈波动，引发鳙鱼（花鲢）产生应激反应，鱼鳃受损后继发维氏气单胞菌感染，致使库区表层鳙鱼（花鲢）死亡。 通报称，近日，亭子湖库区部分水域出现鳙鱼（花鲢）死亡现象。各级各相关部门高度重视，第一时间组织开展打捞处置和原因调查。经四川省重点实验室对送检样本开展病原检测，结合鱼病、水生态领域专家现场勘查，综合研判：9月以来，局部地区晴热高温与短时强降雨交替叠加，造成水体表层水温…"
