    "content": "Meta Platforms挖角MongoDB总裁兼首席执行官Chirantan “CJ” Desai，负责领导面向企业客户的新人工智能平台。该平台被Meta首席执行官马克·扎克伯格视为公司“下一大业务支柱”。扎克伯格周一在X平台发帖称，Desai将出任首席企业平台官，负责面向企业客户的新AI产品。这个名为Meta Enterprise Platform的新业务部门旨在“帮助企业利用AI以新的方式实现增长和转型”。（新浪财经）"
