    "description": "中新网9月29日电 据中央气象台网站消息，昨日，重庆、湖北、贵州等地出现暴雨或大暴雨，新疆、内蒙古等地风力较大。预计未来三天，华西地区至江汉、江淮等地有多阴雨，东北地区南部、华北中部等地有雷暴大风或冰雹等强对流天气，关注对交通、旅游、城市运行等影响；较强冷空气将影响中东部地区，关注大风降温对交通、旅游、农牧业设施等影响。",
