    "content": "2026年09月29日 新华社北京9月28日电&nbsp;&nbsp;9月20日至23日，中美经贸团队在美国纽约和华盛顿举行经贸磋商，取得积极共识，为两国元首会晤贡献了经贸领域的成果。商务部美大司负责人就有关经贸磋商成果进行解读。 一、关于贸易理事会 经过磋商，中美双方同意在中美经贸磋商机制项下建立中美贸易理事会，主要任务是优化双边贸易。双方经贸团队已就理事会的任务、架构、职责、磋商安排等达成共识，将后续公布。贸易理事会将首先就“300亿对300亿”对等降税框架进行讨论，以期达成共识。贸易理事会框架下设立了农业工作…"
