    "description": "2026年09月29日 本报北京9月28日电 （记者王政）工业和信息化部等7部门28日联合印发《新型电池产业发展“十五五”规划》，提出到2030年，我国新体系电池研发取得重大进展，全固态电池初步实现规模化应用。 新型电池是以新机理、新材料、新结构、新工艺为核心创新方向的高效电能存储与转化装置或系统，以锂电池、钠电池、液流电池等为代表。“十四五”时期，我国新型电池产业实现跨越发展，在产业规模、技术创新、产业链建设和全球影响力等方面取得历史…",
    "content": "2026年09月29日 本报北京9月28日电&nbsp;&nbsp;（记者王政）工业和信息化部等7部门28日联合印发《新型电池产业发展“十五五”规划》，提出到2030年，我国新体系电池研发取得重大进展，全固态电池初步实现规模化应用。 新型电池是以新机理、新材料、新结构、新工艺为核心创新方向的高效电能存储与转化装置或系统，以锂电池、钠电池、液流电池等为代表。“十四五”时期，我国新型电池产业实现跨越发展，在产业规模、技术创新、产业链建设和全球影响力等方面取得历史性成就，总产值突破万亿元大关，占据全球市场主要份额；量产电…"
