    "description": "2026年09月29日 本报北京9月28日电 （记者屈信明）记者从金融监管总局、科技部等部门近日联合召开的科技保险交流推进会上获悉：今年前8月，科技保险为科技活动提供风险保障8.7万亿元，同比增长66.9%。 近年来，各部门、各地区和保险机构协同推进，科技保险从试点探索走向体系推进，业务规模快速增长，保障范围持续拓宽。下一步，金融监管、科技、工信、财政、知识产权等部门要强化协调，统筹支持创新与资金安全管理，营造良好发展环境。科技保险要从…",
    "content": "2026年09月29日 本报北京9月28日电&nbsp;&nbsp;（记者屈信明）记者从金融监管总局、科技部等部门近日联合召开的科技保险交流推进会上获悉：今年前8月，科技保险为科技活动提供风险保障8.7万亿元，同比增长66.9%。 近年来，各部门、各地区和保险机构协同推进，科技保险从试点探索走向体系推进，业务规模快速增长，保障范围持续拓宽。下一步，金融监管、科技、工信、财政、知识产权等部门要强化协调，统筹支持创新与资金安全管理，营造良好发展环境。科技保险要从保资产延伸至保过程，从保结果延伸至保探索，从“经济补偿”延…"
