    "pub_date": "2026-09-29 08:26:03",
    "author": "",
    "description": "2026年09月29日 入秋，重庆市垫江县的制种田里，水稻正丰收。10多天前，农户们沿着窄窄的水稻父本行，把授完粉的父本一茬茬割去。父本一清，母本露出来，远远望去，像用尺子划出的一道道线。 现在，逐渐泛黄的水稻母本也到了收割期。稻田绿里浮金，谷穗灌浆饱满。收割机走过，割台转不停，谷粒哗哗落进粮箱。 收下来的稻谷送进烘干车间，机器嗡嗡作响。重庆市农业科学院水稻研究所科研人员管玉圣向记者介绍：“有些商品稻用的是立式烘干机，这种设备像个密封罐…",
    "content": "2026年09月29日 入秋，重庆市垫江县的制种田里，水稻正丰收。10多天前，农户们沿着窄窄的水稻父本行，把授完粉的父本一茬茬割去。父本一清，母本露出来，远远望去，像用尺子划出的一道道线。 现在，逐渐泛黄的水稻母本也到了收割期。稻田绿里浮金，谷穗灌浆饱满。收割机走过，割台转不停，谷粒哗哗落进粮箱。 收下来的稻谷送进烘干车间，机器嗡嗡作响。重庆市农业科学院水稻研究所科研人员管玉圣向记者介绍：“有些商品稻用的是立式烘干机，这种设备像个密封罐，清不干净的话容易串种。制种稻纯度要求高，用不了这种。” 他指了指身旁一台集装箱…"
