    "description": "2026年09月29日 9月16日，平陆运河正式通航。 习近平总书记高度重视平陆运河建设，多次作出重要指示批示，要求高标准、高质量建设平陆运河，打造优质工程、绿色工程、廉洁工程。 作为新中国成立以来建设的首条通江达海的大运河，平陆运河自广西横州平塘江口发端，经灵山陆屋镇，沿钦江汇入北部湾，全长134.2公里，可通航5000吨级船舶。 这是一条开放的运河。作为西部陆海新通道的骨干工程和加快建设交通强国的标志性工程，平陆运河劈山向海，打通西…",
    "content": "2026年09月29日 9月16日，平陆运河正式通航。 习近平总书记高度重视平陆运河建设，多次作出重要指示批示，要求高标准、高质量建设平陆运河，打造优质工程、绿色工程、廉洁工程。 作为新中国成立以来建设的首条通江达海的大运河，平陆运河自广西横州平塘江口发端，经灵山陆屋镇，沿钦江汇入北部湾，全长134.2公里，可通航5000吨级船舶。 这是一条开放的运河。作为西部陆海新通道的骨干工程和加快建设交通强国的标志性工程，平陆运河劈山向海，打通西江与北部湾，为西南地区开辟一条运距最短、最经济、最便捷的南向出海通道，为我国构建…"
