    "content": "2026年09月29日 国庆假期即将到来，带娃自驾出行有哪些需要注意的地方？ 不抱乘。“车辆急刹或发生碰撞时，冲击力大，孩子容易从怀中滑脱，还可能被大人失控的身体挤压，造成二次伤害。”广东省东莞市公安局交通管理支队交通指挥大队三中队副中队长周晨枫提醒，正确的做法是让孩子乘坐后排固定安全座椅，切勿因孩子哭闹而抱着孩子坐车。 不喂食。周晨枫提醒，果冻、话梅、坚果、硬糖以及小巧的圆形水果等尤为危险，一个颠簸、一次急刹，都可能让孩子口中的食物滑入气道，引发窒息。棒棒糖、糖葫芦、烤肠之类的带棍子、签子的食物也要避免在车上喂食…"
