    "description": "2026年09月29日 人工智能与制造业深度融合，正成为推进新型工业化的重要方向。工业和信息化部等八部门印发的《“人工智能+制造”专项行动实施意见》明确提出，鼓励龙头企业、央国企等先行先试，提供规模化应用场景，研发应用工业智能体，先行探索人工智能赋能制造业新模式。对汽车企业而言，如何将人工智能融入核心业务流程，服务产品研发与制造质量提升，是落实这一部署的具体课题。 2023年起，安徽江淮汽车集团股份有限公司（简称“江汽集团”）与华为携手…",
    "content": "2026年09月29日 人工智能与制造业深度融合，正成为推进新型工业化的重要方向。工业和信息化部等八部门印发的《“人工智能+制造”专项行动实施意见》明确提出，鼓励龙头企业、央国企等先行先试，提供规模化应用场景，研发应用工业智能体，先行探索人工智能赋能制造业新模式。对汽车企业而言，如何将人工智能融入核心业务流程，服务产品研发与制造质量提升，是落实这一部署的具体课题。 2023年起，安徽江淮汽车集团股份有限公司（简称“江汽集团”）与华为携手布局高端汽车项目。随着尊界S800、V800等高端产品业务持续推进，江汽集团对研…"
