    "author": "",
    "description": "2026年09月29日 资料图片 \"> 在趋向大制作、强情节、多反转的电影创作潮流中，胡玫导演的《凝脂手》质朴回归现实主义，堪称一部诚意之作。这部影片以湖北钟祥石牌镇豆腐匠人为原型，以弃女潘豆妮的半生浮沉为叙事主线，将个体命运与工匠精神、时代变迁深度交织，展现出主创的艺术功力。 跨年代叙事的关键在人物。如果是以电视剧来表现跨年代戏，会有足够的篇幅去铺陈前情、打磨细节，但放在117分钟的电影里，很容易写成时代进程中的流水账，以至于看不见人…",
    "content": "2026年09月29日 电影《凝脂手》海报。 资料图片 \"> 在趋向大制作、强情节、多反转的电影创作潮流中，胡玫导演的《凝脂手》质朴回归现实主义，堪称一部诚意之作。这部影片以湖北钟祥石牌镇豆腐匠人为原型，以弃女潘豆妮的半生浮沉为叙事主线，将个体命运与工匠精神、时代变迁深度交织，展现出主创的艺术功力。 跨年代叙事的关键在人物。如果是以电视剧来表现跨年代戏，会有足够的篇幅去铺陈前情、打磨细节，但放在117分钟的电影里，很容易写成时代进程中的流水账，以至于看不见人物。电影《凝脂手》牢牢立足于人物，把女主角潘豆妮的难和不向…"
