    "content": "新华社华盛顿9月28日电（记者黄强 徐剑梅）美国总统特朗普28日在社交媒体发文，否认美国媒体有关其愿意以解除对伊朗制裁并解冻资金换取伊朗在核问题上让步的报道。 当天早些时候，美国阿克西奥斯新闻网站援引一名匿名美国官员的话报道，特朗普愿意在伊朗就核问题采取实质性步骤的前提下，解除对伊制裁并解冻伊朗被冻结资金。该官员同时强调，除非伊朗核问题得到解决，否则美国不会与伊朗达成协议，并称双方“在履行承诺的时间节点以及谁先采取行动等问题上”仍存在分歧。 对此，特朗普称，该报道“不实”，“我什么都没有向他们提供”。他还要求该媒体…"
